-- ============================================================
-- MoMoCircle V5 — baseline schema
-- Generated by hand from the current JPA entity mappings
-- (backend/src/main/java/com/momocircle/domain/**) so that the
-- `prod` profile (ddl-auto: validate) has a real schema to
-- validate against instead of relying on Hibernate auto-DDL.
--
-- IMPORTANT: this was authored by reading entity annotations,
-- not generated by hbm2ddl. Before trusting it against a real
-- Postgres deploy, run the app once with
-- spring.jpa.hibernate.ddl-auto=validate against an empty schema
-- created from this file and fix any mismatch Hibernate reports —
-- element-collection table/column names in particular
-- (business_operating_hours, product_image_urls) follow Hibernate's
-- default naming strategy but are worth double-checking.
-- ============================================================

-- ---------- users ----------
CREATE TABLE users (
    id             VARCHAR(36) PRIMARY KEY,
    created_at     TIMESTAMP NOT NULL,
    updated_at     TIMESTAMP NOT NULL,
    email          VARCHAR(255) NOT NULL UNIQUE,
    full_name      VARCHAR(255) NOT NULL,
    phone_number   VARCHAR(255) NOT NULL,
    password_hash  VARCHAR(255) NOT NULL,
    role           VARCHAR(32) NOT NULL,
    active         BOOLEAN NOT NULL DEFAULT TRUE
);

-- ---------- circles ----------
CREATE TABLE circles (
    id            VARCHAR(36) PRIMARY KEY,
    created_at    TIMESTAMP NOT NULL,
    updated_at    TIMESTAMP NOT NULL,
    name          VARCHAR(255) NOT NULL,
    description   VARCHAR(1000),
    type          VARCHAR(32) NOT NULL,
    currency      VARCHAR(3) NOT NULL DEFAULT 'XAF',
    goal_amount   DECIMAL(19,2),
    owner_id      VARCHAR(36) NOT NULL REFERENCES users(id)
);
CREATE INDEX idx_circles_owner ON circles(owner_id);

CREATE TABLE circle_memberships (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    circle_id   VARCHAR(36) NOT NULL REFERENCES circles(id),
    user_id     VARCHAR(36) NOT NULL REFERENCES users(id),
    role        VARCHAR(32) NOT NULL,
    CONSTRAINT uq_membership_circle_user UNIQUE (circle_id, user_id)
);
CREATE INDEX idx_membership_user ON circle_memberships(user_id);

CREATE TABLE circle_invitations (
    id             VARCHAR(36) PRIMARY KEY,
    created_at     TIMESTAMP NOT NULL,
    updated_at     TIMESTAMP NOT NULL,
    circle_id      VARCHAR(36) NOT NULL REFERENCES circles(id),
    invited_by_id  VARCHAR(36) NOT NULL REFERENCES users(id),
    invited_email  VARCHAR(255) NOT NULL,
    role           VARCHAR(32) NOT NULL,
    token          VARCHAR(255) NOT NULL UNIQUE,
    status         VARCHAR(32) NOT NULL,
    expires_at     TIMESTAMP
);
CREATE INDEX idx_invitation_circle ON circle_invitations(circle_id);
CREATE INDEX idx_invitation_email ON circle_invitations(invited_email);

CREATE TABLE circle_goals (
    id             VARCHAR(36) PRIMARY KEY,
    created_at     TIMESTAMP NOT NULL,
    updated_at     TIMESTAMP NOT NULL,
    circle_id      VARCHAR(36) NOT NULL REFERENCES circles(id),
    created_by_id  VARCHAR(36) NOT NULL REFERENCES users(id),
    title          VARCHAR(255) NOT NULL,
    description    VARCHAR(1000),
    target_amount  DECIMAL(19,2) NOT NULL,
    deadline       DATE,
    status         VARCHAR(32) NOT NULL
);
CREATE INDEX idx_goal_circle ON circle_goals(circle_id);

-- ---------- payments (shared financial primitive) ----------
CREATE TABLE payments (
    id                  VARCHAR(36) PRIMARY KEY,
    created_at          TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP NOT NULL,
    amount              DECIMAL(19,2) NOT NULL,
    currency            VARCHAR(3) NOT NULL,
    status              VARCHAR(32) NOT NULL,
    provider            VARCHAR(64) NOT NULL,
    provider_reference  VARCHAR(255),
    idempotency_key     VARCHAR(255) UNIQUE,
    failure_reason      VARCHAR(500)
);
CREATE INDEX idx_payments_status ON payments(status);
CREATE INDEX idx_payments_provider_ref ON payments(provider_reference);

CREATE TABLE payment_requests (
    id                 VARCHAR(36) PRIMARY KEY,
    created_at         TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP NOT NULL,
    circle_id          VARCHAR(36) NOT NULL REFERENCES circles(id),
    requested_by_id    VARCHAR(36) NOT NULL REFERENCES users(id),
    amount_per_member  DECIMAL(19,2) NOT NULL,
    note               VARCHAR(500),
    due_date           DATE,
    status             VARCHAR(32) NOT NULL
);
CREATE INDEX idx_payment_request_circle ON payment_requests(circle_id);
CREATE INDEX idx_payment_request_status_due ON payment_requests(status, due_date);

CREATE TABLE contributions (
    id                  VARCHAR(36) PRIMARY KEY,
    created_at          TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP NOT NULL,
    circle_id           VARCHAR(36) NOT NULL REFERENCES circles(id),
    contributor_id      VARCHAR(36) NOT NULL REFERENCES users(id),
    payment_request_id  VARCHAR(36) REFERENCES payment_requests(id),
    goal_id             VARCHAR(36) REFERENCES circle_goals(id),
    payment_id          VARCHAR(36) NOT NULL UNIQUE REFERENCES payments(id)
);
CREATE INDEX idx_contribution_circle ON contributions(circle_id);
CREATE INDEX idx_contribution_contributor ON contributions(contributor_id);

-- ---------- expenses ----------
CREATE TABLE expenses (
    id           VARCHAR(36) PRIMARY KEY,
    created_at   TIMESTAMP NOT NULL,
    updated_at   TIMESTAMP NOT NULL,
    circle_id    VARCHAR(36) NOT NULL REFERENCES circles(id),
    paid_by_id   VARCHAR(36) NOT NULL REFERENCES users(id),
    description  VARCHAR(255) NOT NULL,
    amount       DECIMAL(19,2) NOT NULL,
    currency     VARCHAR(3) NOT NULL,
    split_type   VARCHAR(32) NOT NULL
);
CREATE INDEX idx_expense_circle ON expenses(circle_id);

CREATE TABLE expense_shares (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    expense_id  VARCHAR(36) NOT NULL REFERENCES expenses(id),
    debtor_id   VARCHAR(36) NOT NULL REFERENCES users(id),
    amount      DECIMAL(19,2) NOT NULL,
    settled     BOOLEAN NOT NULL DEFAULT FALSE,
    settled_at  TIMESTAMP
);
CREATE INDEX idx_expense_share_expense ON expense_shares(expense_id);
CREATE INDEX idx_expense_share_debtor ON expense_shares(debtor_id);

-- ---------- recurring contributions ----------
CREATE TABLE recurring_plans (
    id                 VARCHAR(36) PRIMARY KEY,
    created_at         TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP NOT NULL,
    circle_id          VARCHAR(36) NOT NULL REFERENCES circles(id),
    goal_id            VARCHAR(36) REFERENCES circle_goals(id),
    created_by_id      VARCHAR(36) NOT NULL REFERENCES users(id),
    title              VARCHAR(255) NOT NULL,
    amount_per_member  DECIMAL(19,2) NOT NULL,
    frequency          VARCHAR(32) NOT NULL,
    anchor_date        DATE NOT NULL,
    next_due_date      DATE NOT NULL,
    status             VARCHAR(32) NOT NULL,
    note               VARCHAR(500)
);
CREATE INDEX idx_recurring_plan_circle ON recurring_plans(circle_id);

CREATE TABLE recurring_periods (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    plan_id     VARCHAR(36) NOT NULL REFERENCES recurring_plans(id),
    label       VARCHAR(255) NOT NULL,
    due_date    DATE NOT NULL
);
CREATE INDEX idx_recurring_period_plan ON recurring_periods(plan_id);

CREATE TABLE recurring_dues (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    period_id   VARCHAR(36) NOT NULL REFERENCES recurring_periods(id),
    member_id   VARCHAR(36) NOT NULL REFERENCES users(id),
    amount      DECIMAL(19,2) NOT NULL,
    status      VARCHAR(32) NOT NULL,
    paid_at     TIMESTAMP,
    payment_id  VARCHAR(36) REFERENCES payments(id)
);
CREATE INDEX idx_recurring_due_period ON recurring_dues(period_id);
CREATE INDEX idx_recurring_due_member ON recurring_dues(member_id);

-- ---------- market: businesses & products ----------
CREATE TABLE businesses (
    id              VARCHAR(36) PRIMARY KEY,
    created_at      TIMESTAMP NOT NULL,
    updated_at      TIMESTAMP NOT NULL,
    owner_id        VARCHAR(36) NOT NULL UNIQUE REFERENCES users(id),
    name            VARCHAR(255) NOT NULL,
    description     VARCHAR(2000),
    logo_url        VARCHAR(500),
    category        VARCHAR(255) NOT NULL,
    location        VARCHAR(255),
    contact_phone   VARCHAR(64),
    contact_email   VARCHAR(255),
    active          BOOLEAN NOT NULL DEFAULT TRUE,
    rating_average  DECIMAL(3,2) DEFAULT 0,
    rating_count    INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE business_operating_hours (
    business_id      VARCHAR(36) NOT NULL REFERENCES businesses(id),
    operating_hours  VARCHAR(255)
);
CREATE INDEX idx_business_hours ON business_operating_hours(business_id);

CREATE TABLE products (
    id              VARCHAR(36) PRIMARY KEY,
    created_at      TIMESTAMP NOT NULL,
    updated_at      TIMESTAMP NOT NULL,
    business_id     VARCHAR(36) NOT NULL REFERENCES businesses(id),
    name            VARCHAR(255) NOT NULL,
    description     VARCHAR(2000),
    category        VARCHAR(255) NOT NULL,
    price           DECIMAL(19,2) NOT NULL,
    currency        VARCHAR(3) NOT NULL DEFAULT 'XAF',
    is_service      BOOLEAN NOT NULL DEFAULT FALSE,
    stock           INTEGER NOT NULL DEFAULT 0,
    status          VARCHAR(32) NOT NULL,
    rating_average  DECIMAL(3,2) DEFAULT 0,
    rating_count    INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_product_business ON products(business_id);
CREATE INDEX idx_product_status ON products(status);

CREATE TABLE product_image_urls (
    product_id  VARCHAR(36) NOT NULL REFERENCES products(id),
    image_urls  VARCHAR(500)
);
CREATE INDEX idx_product_images ON product_image_urls(product_id);

CREATE TABLE cart_items (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    user_id     VARCHAR(36) NOT NULL REFERENCES users(id),
    product_id  VARCHAR(36) NOT NULL REFERENCES products(id),
    quantity    INTEGER NOT NULL,
    CONSTRAINT uq_cart_user_product UNIQUE (user_id, product_id)
);
CREATE INDEX idx_cart_user ON cart_items(user_id);

-- ---------- market: orders ----------
CREATE TABLE orders (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    buyer_id    VARCHAR(36) NOT NULL REFERENCES users(id),
    business_id VARCHAR(36) NOT NULL REFERENCES businesses(id),
    subtotal    DECIMAL(19,2) NOT NULL,
    total       DECIMAL(19,2) NOT NULL,
    currency    VARCHAR(3) NOT NULL,
    status      VARCHAR(32) NOT NULL,
    -- NOTE: stored as a plain string, not an FK, matching Order.java today.
    -- Worth tightening to a real FK to payments(id) in a follow-up migration
    -- once every write path that sets it is confirmed to always reference a
    -- real Payment row.
    payment_id  VARCHAR(36)
);
CREATE INDEX idx_order_buyer ON orders(buyer_id);
CREATE INDEX idx_order_business ON orders(business_id);
CREATE INDEX idx_order_payment ON orders(payment_id);

CREATE TABLE order_items (
    id                    VARCHAR(36) PRIMARY KEY,
    created_at            TIMESTAMP NOT NULL,
    updated_at            TIMESTAMP NOT NULL,
    order_id              VARCHAR(36) NOT NULL REFERENCES orders(id),
    product_id            VARCHAR(36) NOT NULL REFERENCES products(id),
    product_name_snapshot VARCHAR(255) NOT NULL,
    unit_price_snapshot   DECIMAL(19,2) NOT NULL,
    quantity              INTEGER NOT NULL,
    line_total            DECIMAL(19,2) NOT NULL
);
CREATE INDEX idx_order_item_order ON order_items(order_id);

CREATE TABLE reviews (
    id           VARCHAR(36) PRIMARY KEY,
    created_at   TIMESTAMP NOT NULL,
    updated_at   TIMESTAMP NOT NULL,
    author_id    VARCHAR(36) NOT NULL REFERENCES users(id),
    target_type  VARCHAR(32) NOT NULL,
    target_id    VARCHAR(36) NOT NULL,
    order_id     VARCHAR(36) NOT NULL REFERENCES orders(id),
    rating       INTEGER NOT NULL,
    text         VARCHAR(1000),
    hidden       BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT uq_review_author_target UNIQUE (author_id, target_type, target_id)
);
CREATE INDEX idx_review_target ON reviews(target_type, target_id);

CREATE TABLE receipts (
    id                  VARCHAR(36) PRIMARY KEY,
    created_at          TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP NOT NULL,
    receipt_number      VARCHAR(64) NOT NULL UNIQUE,
    payment_id          VARCHAR(36) NOT NULL UNIQUE REFERENCES payments(id),
    payer_id            VARCHAR(36) NOT NULL REFERENCES users(id),
    payee_label         VARCHAR(255) NOT NULL,
    description         VARCHAR(500) NOT NULL,
    amount              DECIMAL(19,2) NOT NULL,
    currency            VARCHAR(3) NOT NULL,
    status              VARCHAR(32) NOT NULL,
    provider_reference  VARCHAR(255)
);
CREATE INDEX idx_receipt_payer ON receipts(payer_id);

-- ---------- notifications / activity / audit ----------
CREATE TABLE notifications (
    id            VARCHAR(36) PRIMARY KEY,
    created_at    TIMESTAMP NOT NULL,
    updated_at    TIMESTAMP NOT NULL,
    recipient_id  VARCHAR(36) NOT NULL REFERENCES users(id),
    type          VARCHAR(32) NOT NULL,
    message       VARCHAR(500) NOT NULL,
    reference_id  VARCHAR(255),
    read          BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX idx_notification_recipient ON notifications(recipient_id, read);

CREATE TABLE activity_events (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    circle_id   VARCHAR(36) NOT NULL REFERENCES circles(id),
    actor_id    VARCHAR(36) REFERENCES users(id),
    type        VARCHAR(32) NOT NULL,
    message     VARCHAR(500) NOT NULL
);
CREATE INDEX idx_activity_circle ON activity_events(circle_id);

CREATE TABLE audit_logs (
    id          VARCHAR(36) PRIMARY KEY,
    created_at  TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP NOT NULL,
    actor_id    VARCHAR(36) REFERENCES users(id),
    action      VARCHAR(255) NOT NULL,
    target_type VARCHAR(255),
    target_id   VARCHAR(255),
    details     VARCHAR(1000)
);
CREATE INDEX idx_audit_actor ON audit_logs(actor_id);
CREATE INDEX idx_audit_target ON audit_logs(target_type, target_id);
